362	// CancelPlanChange 在安排生效前取消它，取消后账户继续沿用当前套餐。
363	// 没有待生效安排时取消也成功；已生效的切换不会被撤回。
364	// 欠费停用期间也可以取消，取消不清除欠费、不解除停用。
365	// 账户不存在、订阅已终止（含已到终止时刻）时失败。
366	func (s *Service) CancelPlanChange(accountID string) error {
367		if accountID == "" {
368			return invalidf("account id is empty")
369		}
370		s.mu.Lock()
371		defer s.mu.Unlock()
372		acc, ok := s.accounts[accountID]
373		if !ok {
374			return ErrAccountNotFound
375		}
376		// 已到生效月份月初零点的安排视为已生效，不可撤回；已终止订阅段无当前订阅。
377		s.settleLocked(acc, s.nowUTC())
378		if acc.sub == nil {
379			return ErrSubscriptionNotFound
380		}
381		acc.sub.pending = nil
382		return nil
383	}
