458	// RecordEvent 上报一条用量事件。
459	//
460	// 事件按发生时刻归入 UTC 自然月账期；事件发生时刻必须属于某段实际订阅期间
461	// （开通时刻计入、终止时刻不计入），空档期间与晚于当前时刻的事件被拒绝。
462	// 订阅终止后仍可补报旧订阅期间且尚未出账的用量。
463	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计——
464	// 即使发生在取消、重新开通之后也成功；相同标识但时刻或数量不同返回
465	// ErrEventConflict。
466	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新增事件；
467	// 但此前已接收事件的完全相同重报始终成功。
468	func (s *Service) RecordEvent(e Event) (EventResult, error) {
469		if e.AccountID == "" {
470			return EventResult{}, invalidf("account id is empty")
471		}
472		if e.EventID == "" {
473			return EventResult{}, invalidf("event id is empty")
474		}
475		if e.Quantity < 0 {
476			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
477		}
478		if e.At.IsZero() {
479			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
480		}
481		at := e.At.UTC()
482	
483		s.mu.Lock()
484		defer s.mu.Unlock()
485	
486		acc, ok := s.accounts[e.AccountID]
487		if !ok {
488			return EventResult{}, ErrAccountNotFound
489		}
490	
491		now := s.nowUTC()
492		// 进入即补齐已到期的换套餐/取消，保证并发下各操作观察到一致的分段状态。
493		s.settleLocked(acc, now)
494	
495		// 从未开通订阅的账户没有任何订阅段。
496		if acc.sub == nil && len(acc.history) == 0 {
497			return EventResult{}, ErrSubscriptionNotFound
498		}
499	
500		// 去重优先：完全相同的重报即使发生在出账后、停用期间、取消或重新开通
501		// 之后也返回成功。
502		if prev, ok := acc.events[e.EventID]; ok {
503			if !prev.at.Equal(at) || prev.qty != e.Quantity {
504				return EventResult{}, ErrEventConflict
505			}
506			return EventResult{Accepted: false, Period: prev.period}, nil
507		}
508	
509		if at.After(now) {
510			return EventResult{}, ErrEventInFuture
511		}
512		// 事件发生时刻必须落在某段实际订阅期间：[activatedAt, end)。
513		if activeSegmentAtLocked(acc, at) == nil {
514			return EventResult{}, ErrEventBeforeSubscription
515		}
516	
517		period := MonthOf(at)
518		if _, billed := acc.bills[period]; billed {
519			return EventResult{}, ErrMonthBilled
520		}
521		if s.isSuspendedLocked(acc, now) {
522			return EventResult{}, ErrSuspended
523		}
524	
525		total, ok := addNonNeg(acc.usage[period], e.Quantity)
526		if !ok {
527			return EventResult{}, ErrOverflow
528		}
529		// 所有校验通过后才落库：失败不消耗事件标识。
530		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
531		acc.usage[period] = total
532		return EventResult{Accepted: true, Period: period}, nil
533	}
