604	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
605	// 付款标识在同一账户内去重：相同账单和金额的重报仍成功，但本次不再登记
606	// （Registered 为 false），也不再次增加已付金额；返回的付款内容、账单余额与
607	// 付清状态均为该笔付款首次成功登记完成时的历史结果，不随后续付款或账单当前
608	// 状态变化（例如账单后来已结清，重报早先的部分付款仍返回当时的未清余额与
609	// 未付清）。账单查询与账户状态中的余额始终反映当前状态，不受重报影响。
610	// 相同标识但账期或金额不同返回 ErrPaymentConflict：即使原账单已结清，或改指
611	// 向的账期还没有账单，也按冲突处理而非当作新付款。失败不消耗付款标识。
612	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
613		if accountID == "" {
614			return PaymentResult{}, invalidf("account id is empty")
615		}
616		if paymentID == "" {
617			return PaymentResult{}, invalidf("payment id is empty")
618		}
619		if amount <= 0 {
620			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
621		}
622		s.mu.Lock()
623		defer s.mu.Unlock()
624	
625		acc, ok := s.accounts[accountID]
626		if !ok {
627			return PaymentResult{}, ErrAccountNotFound
628		}
629		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
630		if prev, ok := acc.payments[paymentID]; ok {
631			if prev.period != period || prev.amount != amount {
632				return PaymentResult{}, ErrPaymentConflict
633			}
634			// 完全相同的重报仍成功，但不再次登记、不改变账单：
635			// 返回这笔付款首次成功登记完成时的余额与付清状态，
636			// 不受账单后续收款、当前余额或停用/恢复状态影响。
637			return PaymentResult{
638				Registered:  false,
639				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
640				BillBalance: prev.balance,
641				Settled:     prev.settled,
642			}, nil
643		}
644	
645		rec, ok := acc.bills[period]
646		if !ok {
647			return PaymentResult{}, ErrBillNotFound
648		}
649	
650		if amount > rec.bill.Balance {
651			return PaymentResult{}, ErrPaymentExceedsBalance
652		}
653	
654		paid, ok := addNonNeg(rec.bill.Paid, amount)
655		if !ok {
656			return PaymentResult{}, ErrOverflow
657		}
658		rec.bill.Paid = paid
659		rec.bill.Balance -= amount
660		if rec.bill.Balance == 0 {
661			rec.bill.Settled = true
662		}
663		// 保存首次登记完成时的历史结果，供完全相同重报原样返回。
664		acc.payments[paymentID] = paymentRecord{
665			period:  period,
666			amount:  amount,
667			balance: rec.bill.Balance,
668			settled: rec.bill.Settled,
669		}
670	
671		return PaymentResult{
672			Registered:  true,
673			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
674			BillBalance: rec.bill.Balance,
675			Settled:     rec.bill.Settled,
676		}, nil
677	}
