695	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
696	func (s *Service) Status(accountID string) (AccountStatus, error) {
697		if accountID == "" {
698			return AccountStatus{}, invalidf("account id is empty")
699		}
700		s.mu.Lock()
701		defer s.mu.Unlock()
702		acc, ok := s.accounts[accountID]
703		if !ok {
704			return AccountStatus{}, ErrAccountNotFound
705		}
706	
707		now := s.nowUTC()
708		// 查询即让已到期安排/取消生效：月初零点或终止时刻之后无需上报用量或出账，
709		// 当前条件与订阅状态立即更新。
710		s.settleLocked(acc, now)
711	
712		// 订阅是否生效以实际开通时刻为界：提前登记、开通时刻尚未到达的订阅仍
713		// 保存在 acc.sub 中（再次开通、安排换套餐、登记取消均按已有订阅的规则
714		// 处理），但查询时刻不显示为有效订阅。到达开通时刻即生效，不按开通月份
715		// 提前生效；时刻按同一瞬间比较，使用带时区的时间结果一致。
716		active := acc.sub != nil && !now.Before(acc.sub.activatedAt)
717	
718		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
719		for m := range acc.usage {
720			periodSet[m] = struct{}{}
721		}
722		for m := range acc.bills {
723			periodSet[m] = struct{}{}
724		}
725		periods := make([]Month, 0, len(periodSet))
726		for m := range periodSet {
727			periods = append(periods, m)
728		}
729		sortMonths(periods)
730	
731		st := AccountStatus{
732			AccountID:    accountID,
733			Subscribed:   active,
734			Suspended:    s.isSuspendedLocked(acc, now),
735			MonthlyUsage: make([]Usage, 0, len(periods)),
736			Bills:        make([]BillSummary, 0, len(acc.bills)),
737		}
738		// 仅实际生效的订阅才展示当前套餐条件、待换套餐安排与已安排终止时刻；
739		// 等待开通期间这些字段均为零值（查询不删除也不提前激活已登记订阅）。
740		if active {
741			// 当前条件与历史出账取自同一份条件时间线：月初零点 settleLocked
742			// 追加新快照后，这里直接拿到安排时锁定的完整条件，无需另行同步。
743			st.CurrentTerms = termsForPeriod(acc.sub, MonthOf(now))
744			if acc.sub.pending != nil {
745				pending := *acc.sub.pending
746				st.PendingChange = &pending
747			}
748			if acc.sub.cancelEnd != nil {
749				end := *acc.sub.cancelEnd
750				st.ScheduledEnd = &end
751			}
752		}
753		for _, m := range periods {
754			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
755		}
756		for _, m := range periods {
757			if rec, ok := acc.bills[m]; ok {
758				b := rec.bill
759				st.Bills = append(st.Bills, BillSummary{
760					Period:   m,
761					TotalDue: b.TotalDue,
762					Paid:     b.Paid,
763					Balance:  b.Balance,
764					Settled:  b.Settled,
765					DueAt:    b.DueAt,
766				})
767			}
768		}
769		return st, nil
770	}
771	
772	// isSuspendedLocked 报告账户当前是否停用：
773	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
774	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
775		for _, rec := range acc.bills {
776			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
777				return true
778			}
779		}
780		return false
781	}
782	
783	func sortMonths(ms []Month) {
784		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
785	}
786	
787	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
788	func addNonNeg(a, b int64) (int64, bool) {
789		if a > maxInt64-b {
790			return 0, false
791		}
792		return a + b, true
793	}
794	
795	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
796	func mulNonNeg(a, b int64) (int64, bool) {
797		if a == 0 || b == 0 {
798			return 0, true
799		}
800		if a > maxInt64/b {
801			return 0, false
802		}
803		return a * b, true
804	}
805	
806	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
807	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
808		overageUnits := int64(0)
809		if totalUsage > t.IncludedUnits {
810			overageUnits = totalUsage - t.IncludedUnits
811		}
812		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
813		if !ok {
814			return Bill{}, ErrOverflow
815		}
816		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
817		if !ok {
818			return Bill{}, ErrOverflow
819		}
820		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
821		if !ok {
822			return Bill{}, ErrOverflow
823		}
824		totalDue, ok := addNonNeg(subtotal, tax)
825		if !ok {
826			return Bill{}, ErrOverflow
827		}
828		b := Bill{
829			AccountID:     accountID,
830			Period:        period,
831			Terms:         t,
832			TotalUsage:    totalUsage,
833			IncludedUnits: t.IncludedUnits,
834			OverageUnits:  overageUnits,
835			MonthlyFee:    t.MonthlyFee,
836			OverageFee:    overageFee,
837			Tax:           tax,
838			TotalDue:      totalDue,
839			Paid:          0,
840			Balance:       totalDue,
841			Settled:       totalDue == 0,
842			DueAt:         period.End().AddDate(0, 0, 7),
843		}
844		return b, nil
845	}
846	
847	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
848	// 拆分商和余数计算以避免乘积溢出 int64。
849	func rateAmount(amount, rate int64) (int64, bool) {
850		const den = 10000
851		q, r := amount/den, amount%den
852		qr, ok := mulNonNeg(q, rate)
853		if !ok {
854			return 0, false
855		}
856		rr, ok := mulNonNeg(r, rate)
857		if !ok {
858			return 0, false
859		}
860		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
861		add, ok := addNonNeg(qr, (rr+den/2)/den)
862		if !ok {
863			return 0, false
864		}
865		return add, true
866	}
867

